/**
 * The plan for each benchmark scenario: pure data, no calendar import, so both
 * the browser app (which builds the events from it) and the Playwright specs
 * (which decide what to drive) read the same description.
 */

export type ViewName = 'day' | 'week' | 'month' | 'year'

export interface Plan {
	id: string
	description: string
	view: ViewName
	orientation?: 'vertical' | 'horizontal'
	slotDuration?: 15 | 30 | 60
	/** Resource count; absent for a calendar without a resource axis. */
	resources?: number
	/** Events generated by the seeded generator (the drag subject is extra). */
	events: number
	/** `perResource`: `events` is per resource rather than in total. */
	eventsPerResource?: boolean
	/** 50 daily series from the recurrence plugin instead of plain events. */
	recurringSeries?: number
	plugins?: Array<'recurrence'>
	/** Which element family draws the bars: vertical (time grid) or horizontal. */
	bar: 'vertical' | 'horizontal'
	/** Drag the subject this many cells right and down. Absent: the view has no drag. */
	drag?: { dx: number; dy: number }
	/** Drag the subject's end handle this many cells right and down. */
	resize?: { dx: number; dy: number }
	/** Drag the subject to the container's edge and hold. */
	autoscroll?: 'down'
	/** Views switched to (and back from) to time a view switch. */
	switchTo: ViewName[]
}

